### Contoh

```js
import { mkdir, readdir, writeFile, stat } from 'node:fs/promises';

await mkdir('laporan/2026', { recursive: true });
await writeFile('laporan/2026/nov.txt', 'penjualan 12 juta');

for (const e of await readdir('laporan', { withFileTypes: true })) {
  console.log(e.name, e.isDirectory() ? 'folder' : 'file');
}

const info = await stat('laporan/2026/nov.txt');
console.log(info.size); // ukuran dalam byte
```

Urutan hasil `readdir` **tidak dijamin** sama di setiap sistem. Kalau urutan penting, urutkan dengan `.sort()`.

