import { mkdir, writeFile, readdir, stat, rm, rename } from 'node:fs/promises';
await mkdir('arsip/2026/nov', { recursive: true });
await writeFile('arsip/2026/nov/a.txt', 'Kopi');
await writeFile('arsip/2026/nov/b.txt', 'Teh Tarik');
await writeFile('arsip/2026/catatan.md', '# Catatan');
const isi = (await readdir('arsip/2026', { withFileTypes: true }))
  .map((e) => e.name + (e.isDirectory() ? '/' : ''))
  .sort();
console.log(isi);
console.log((await stat('arsip/2026/nov/b.txt')).size);
await rename('arsip/2026/nov/a.txt', 'arsip/2026/nov/kopi.txt');
await rm('arsip/2026/catatan.md');
console.log((await readdir('arsip/2026/nov')).sort());

